const rtdal003955Source0003 = `for (i in 1:12) {
  for (j in 1:12) {
    N_DAYS_BETWEEN_MONTHS_LOWER[[i, j]] <-
      if (i < j) {
        sum(N_DAYS_IN_MONTHS[i:(j - 1)])
      } else if (j < i) {
        sum(N_DAYS_IN_MONTHS[-(j:(i - 1))])
      } else {
        0L
      }
  }
}`

