const rtdal003962Source0001 = `check_duration <- function(object) {
  if (is.numeric(object@.Data)) {
    TRUE
  } else {
    "Duration value is not a number. Should be numeric."
  }
}`

const rtdal003962Source0005 = `.readable_duration <- function(x, unit) {
  if (unit == "second") {
    paste0(x, "s")
  } else {
    x2 <- round(x / SECONDS_IN_ONE[[unit]], 2)
    sprintf("%ss (~%s %ss)", x, x2, unit)
  }
}`

