const rtdal003962Source0016 = `duration <- function(num = NULL, units = "seconds", ...) {
  if (is.character(num)) {
    as.duration(parse_period(num))
  } else {
    out1 <- .duration_from_num(num, units)
    out2 <- .duration_from_pieces(list(...))
    if (is.null(out1) && is.null(out2)) {
      new("Duration", numeric())
    } else if (is.null(out1)) {
      out2
    } else if (is.null(out2)) {
      out1
    } else {
      c(out1, out2)
    }
  }
}`

const rtdal003962Source0019 = `.duration_from_pieces <- function(pieces) {
  if (length(pieces) == 0) {
    return(NULL)
  }
  names(pieces) <- standardise_date_names(names(pieces))
  out <- 0
  for (nm in names(pieces)) {
    out <- out + pieces[[nm]] * average_durations[[nm]]
  }
  new("Duration", out)
}`

const rtdal003962Source0032 = "summary.Duration <- function(object, ...) {\n  nas <- is.na(object)\n  object <- object[!nas]\n  nums <- as.numeric(object)\n  qq <- stats::quantile(nums)\n  qq <- c(qq[1L:3L], mean(nums), qq[4L:5L])\n  qq <- dseconds(qq)\n  qq <- as.character(qq)\n  names(qq) <- c(\n    \"Min.\", \"1st Qu.\", \"Median\", \"Mean\", \"3rd Qu.\",\n    \"Max.\"\n  )\n  if (any(nas)) {\n    c(qq, `NA's` = sum(nas))\n  } else {\n    qq\n  }\n}"

