const rtdal003967Source0047 = "summary.Interval <- function(object, ...) {\n  nas <- is.na(object)\n  object <- object[!nas]\n  n <- length(object)\n  dates <- c(int_start(object), int_end(object))\n  earliest <- as.character(min(dates))\n  latest <- as.character(max(dates))\n  zone <- tz(dates)\n\n  qq <- c(n, earliest, latest, zone)\n  names(qq) <- c(\"Intervals\", \"Earliest endpoint\", \"Latest endpoint\", \"Time zone\")\n  if (any(nas)) {\n    c(qq, `NA's` = sum(nas))\n  } else {\n    qq\n  }\n}"

const rtdal003967Source0048 = `setMethod("time_length", signature("Interval"), function(x, unit = "second") {
  unit <- standardise_period_names(unit)
  if (unit %in% c("year", "month")) {
    periods <- as.period(x, unit = unit)
    int_part <- slot(periods, unit)

    prev_aniv <- add_with_rollback(
      int_start(x), (int_part * period(1, units = unit)),
      roll_to_first = TRUE, preserve_hms = FALSE
    )
    next_aniv <- add_with_rollback(
      int_start(x), ((int_part + ifelse(x@.Data < 0, -1, 1)) * period(1, units = unit)),
      roll_to_first = TRUE, preserve_hms = FALSE
    )

    sofar <- as.duration(int_end(x) - prev_aniv)
    total <- as.duration(next_aniv - prev_aniv)
    int_part + sign(x@.Data) * sofar / total
  } else {
    as.duration(x) / duration(num = 1, units = unit)
  }
})`

