const rtdal003970Source0003 = `add_duration_to_date <- function(dur, date) {
  if (is.Date(date)) {
    date <- as.POSIXct(date)
    ans <- with_tz(date + dur@.Data, "UTC")

    if (all(is.na(ans))) {
      return(as.Date(ans))
    } # ALL NAs

    if (all(hour(na.omit(ans)) == 0 &
      minute(na.omit(ans)) == 0 &
      second(na.omit(ans)) == 0)) {
      return(as.Date(ans))
    }

    return(ans)
  }
  new <- date + dur@.Data
  attr(new, "tzone") <- tz(date)
  reclass_date(new, date)
}`

const rtdal003970Source0005 = `add_period_to_date <- function(per, date) {
  out <-
    timechange::time_add(date,
      years = per@year,
      months = per@month,
      days = per@day,
      hours = per@hour,
      minutes = per@minute,
      seconds = per@.Data,
      roll_month = "NA",
      roll_dst = c("NA", "pre"))
  if (is.Date(date) && is_zero_hms(per@hour, per@minute, per@.Data))
    out <- as_date(out)
  out
}`

const rtdal003970Source0007 = `add_number_to_period <- function(num, per) {
  slot(per, ".Data") <- per@.Data + num
  per
}`

