const rtdal003979Source0026 = `.parse_hms <- function(..., order, quiet = FALSE) {
  ## wrapper for C level parse_hms
  hms <- unlist(lapply(list(...), .num_to_date), use.names = FALSE)
  out <- matrix(.Call(C_parse_hms, hms, order),
    nrow = 3L, dimnames = list(c("H", "M", "S"), NULL)
  )
  if (!quiet) {
    ## fixme: this warning should be dropped to C and thrown only when there are
    ## real parsing errors #530
    sym <- substr(order, ln <- nchar(order), ln)
    if (any(is.na(out[sym, ]) & !is.na(hms))) {
      warning("Some strings failed to parse")
    }
  }
  out
}`

const rtdal003979Source0027 = "parse_date_time <- function(x, orders, tz = \"UTC\", truncated = 0, quiet = FALSE,\n                            locale = Sys.getlocale(\"LC_TIME\"), select_formats = .select_formats,\n                            exact = FALSE, train = TRUE, drop = FALSE) {\n\n  ## backward compatible hack\n  if (is.null(tz)) tz <- \"\"\n  if (length(tz) != 1 || is.na(tz)) {\n    stop(\"`tz` argument must be a character of length one\")\n  }\n\n  orig_locale <- Sys.getlocale(\"LC_TIME\")\n  Sys.setlocale(\"LC_TIME\", locale)\n  on.exit(Sys.setlocale(\"LC_TIME\", orig_locale))\n\n  x <- as.character(.num_to_date(x))\n  if (truncated != 0) {\n    orders <- .add_truncated(orders, truncated)\n  }\n\n  .local_parse <- function(x, first = FALSE) {\n    formats <-\n      if (exact) {\n        orders\n      } else {\n        trainset <- .get_train_set(x)\n        .best_formats(trainset, orders, locale = locale, select_formats, drop = drop, train = train)\n      }\n    if (length(formats) > 0) {\n      out <- .parse_date_time(x, formats, tz = tz, quiet = quiet, locale = locale)\n      new_na <- is.na(out)\n      if (any(new_na)) {\n        x <- x[new_na]\n        if (length(x) == length(out)) {\n          # don't recur if failed for all\n          failed <<- length(x)\n        } else {\n          out[new_na] <- .local_parse(x)\n        }\n      }\n      out\n    } else {\n      if (first && !quiet) {\n        warning(\"All formats failed to parse. No formats found.\", call. = FALSE)\n        warned <<- TRUE\n      }\n      failed <<- length(x)\n      NA\n    }\n  }\n\n  failed <- 0L\n  warned <- FALSE\n  to_parse <- which(!is.na(x) & nzchar(x)) ## missing data might be \"\"\n  ## prepare an NA vector\n  out <- .POSIXct(rep.int(NA_real_, length(x)), tz = tz)\n\n  if (length(to_parse)) {\n    out[to_parse] <- .local_parse(x[to_parse], TRUE)\n    if (failed > 0 && !quiet && !warned) {\n      warning(\" \", failed, \" failed to parse.\", call. = FALSE)\n    }\n  }\n\n  out\n}"

const rtdal003979Source0029 = "parse_date_time2 <- function(x, orders, tz = \"UTC\", exact = FALSE, lt = FALSE, cutoff_2000 = 68L) {\n  if (length(tz) != 1 || is.na(tz)) {\n    stop(\"`tz` argument must be a character of length one\")\n  }\n  parse1 <- function(x, order) {\n    if (!exact) {\n      order <- gsub(\"[^[:alpha:]]+\", \"\", as.character(order))\n    }\n    if (lt) {\n      .mklt(parse_dt(x, order, exact, TRUE, cutoff_2000), tz)\n    } else {\n      if (is_utc(tz)) {\n        .POSIXct(parse_dt(x, order, exact, FALSE, cutoff_2000), tz = \"UTC\")\n      } else {\n        as.POSIXct(.mklt(parse_dt(x, order, exact, TRUE, cutoff_2000), tz))\n      }\n    }\n  }\n  nnas <- !is.na(x)\n  out <- parse1(x, orders[[1]])\n  for (order in orders[-1]) {\n    nnas <- nnas & is.na(out)\n    out[nnas] <- parse1(x[nnas], order)\n  }\n  out\n}"

const rtdal003979Source0030 = `fast_strptime <- function(x, format, tz = "UTC", lt = TRUE, cutoff_2000 = 68L) {
  parse1 <- function(x, fmt) {
    if (lt) {
      .mklt(parse_dt(x, fmt, TRUE, TRUE, cutoff_2000), tz)
    } else {
      if (is_utc(tz)) {
        .POSIXct(parse_dt(x, fmt, TRUE, FALSE, cutoff_2000), "UTC")
      } else {
        as.POSIXct(.mklt(parse_dt(x, fmt, TRUE, TRUE, cutoff_2000), tz))
      }
    }
  }
  nnas <- !is.na(x)
  out <- parse1(x, format[[1]])
  for (fmt in format[-1]) {
    nnas <- nnas & is.na(out)
    out[nnas] <- parse1(x[nnas], fmt)
  }
  out
}`

const rtdal003979Source0033 = `.strptime <- function(x, fmt, tz = "UTC", quiet = FALSE, locale = NULL) {

  ## Depending on fmt we might need to preprocess x.
  ## ISO8601 and internal parser are the only cases so far.
  ## %Ou: "2013-04-16T04:59:59Z"
  ## %Oo: "2013-04-16T04:59:59+01"
  ## %Oz: "2013-04-16T04:59:59+0100"
  ## %OO: "2013-04-16T04:59:59+01:00"

  ## is_posix <-  0 < regexpr("^[^%]*%Y[^%]+%m[^%]+%d[^%]+(%H[^%](%M[^%](%S)?)?)?[^%Z]*$", fmt)

  c_parser <- 0 < regexpr("^[^%0-9]*(%([YymdqIHMSz]|O[SzuoOpmb])[^%0-9Z]*)+$", fmt)
  zpos <- regexpr("%O((?<z>z)|(?<u>u)|(?<o>o)|(?<O>O))", fmt, perl = TRUE)

  if (c_parser) {
    ## C PARSER:
    out <- fast_strptime(x, fmt, tz = "UTC", lt = FALSE)

    if (!is_utc(tz)) {
      out <-
        if (zpos > 0) {
          if (!quiet) {
            message("Date in ISO8601 format; converting timezone from UTC to \"", tz, "\".")
          }
          with_tz(out, tzone = tz)
        } else {
          ## force_tz is very slow
          force_tz(out, tzone = tz)
        }
    }

    out
  } else {
    ## STRPTIME PARSER:

    ## strptime doesn't accept 'locale' argument; need a hard reset
    if (!is.null(locale)) {
      old_lc_time <- Sys.getlocale("LC_TIME")
      if (old_lc_time != locale) {
        Sys.setlocale("LC_TIME", locale)
        on.exit(Sys.setlocale("LC_TIME", old_lc_time))
      }
    }

    if (zpos > 0) {
      ## If ISO8601 -> pre-process x and fmt
      capt <- attr(zpos, "capture.names")[attr(zpos, "capture.start") > 0][[2]] ## <- second subexp
      repl <- switch(capt,
        z = "%z",
        u = "Z",
        ## substitute +aa with +aa00
        o = {
          x <- sub("([+-]\\d{2}(?=\\D+)?$)", "\\100", x, perl = TRUE)
          "%z"
        },
        ## substitute +aa:bb with +aabb
        O = {
          x <- sub("([+-]\\d{2}):(?=[^:]+$)", "\\1", x, perl = TRUE)
          "%z"
        },
        stop("Unrecognised capture detected; please report this bug")
      )

      fmt <- .str_sub(fmt, zpos, zpos + attr(zpos, "match.length") - 1, repl)

      ## user has supplied tz argument -> convert to tz
      if (!is_utc(tz)) {
        if (!quiet) {
          message("Date in ISO8601 format; converting timezone from UTC to \"", tz, "\".")
        }
        return(with_tz(strptime(.enclose(x), .enclose(fmt), "UTC"), tzone = tz))
      }
    }

    ## Replace any remaining %Ob formats which strptime does not understand. Can happen
    ## when fmt contains %a which are not currently handled in c_parser. #1104
    fmt <- gsub("%O([Bb])", "%\\1", fmt)

    strptime(.enclose(x), .enclose(fmt), tz)
  }
}`

const rtdal003979Source0036 = `.parse_xxx_hms <- function(..., orders, truncated, quiet, tz, locale) {
  ## !!! NOTE: truncated operates on first element in ORDERS !
  if (truncated > 0) {
    ## Take first 3 formats and append formats from .xxx_hms_truncations
    ## co responding to the 4th format letter in order[[1]] -- T, R or r.
    xxx <- substr(orders[[1]], 1, 3) ##
    add <- paste(xxx, .xxx_hms_truncations[[substr(orders[[1]], 4, 4)]], sep = "")
    rest <- length(add) - truncated
    if (rest < 0) {
      orders <- c(orders, add, .add_truncated(xxx, abs(rest)))
    } else {
      orders <- c(orders, add[1:truncated])
    }
  }
  dates <- unlist(lapply(list(...), .num_to_date), use.names = FALSE)
  parse_date_time(dates, orders, tz = tz, quiet = quiet, locale = locale, )
}`

const rtdal003979Source0037 = `.parse_xxx <- function(..., orders, quiet, tz, locale, truncated) {
  dates <- unlist(lapply(list(...), .num_to_date), use.names = FALSE)
  if (is.null(tz)) {
    as.Date.POSIXct(parse_date_time(dates, orders,
      quiet = quiet, tz = "UTC",
      locale = locale, truncated = truncated
    ))
  } else {
    parse_date_time(dates, orders,
      quiet = quiet, tz = tz,
      locale = locale, truncated = truncated
    )
  }
}`

const rtdal003979Source0038 = `.num_to_date <- function(x) {
  if (is.numeric(x)) {
    prefix0 <- any(x > 1900, na.rm = TRUE)
    out <- rep.int(as.character(NA), length(x))
    nnas <- !is.na(x)
    x <- format(x[nnas], scientific = FALSE, trim = TRUE)
    # #1002 lower numbers are normally something else than full dates
    if (prefix0) {
      x <- paste(ifelse(nchar(x) %% 2 == 1, "0", ""), x, sep = "")
    }
    out[nnas] <- x
    out
  } else {
    as.character(x)
  }
}`

const rtdal003979Source0040 = `as_POSIXct <- function(x, tz = tz(x)) {
  if (is.character(x)) {
    .parse_iso_dt(x, tz = tz)
  } else if (is.Date(x)) {
    ## as.POSIXct.Date assues UTC in computation but returns POSIXct with system TZ
    ## same as as_datetime Date method
    .POSIXct(as.numeric(x) * 86400, tz = "UTC")
  } else if (!is.POSIXct(x)) {
    as.POSIXct(x, tz = tz)
  } else {
    x
  }
}`

