const rtdal003980Source0002 = `check_period <- function(object) {
  errors <- character()

  length(object@.Data) -> n
  lengths <- c(
    length(object@year), length(object@month),
    length(object@day), length(object@hour), length(object@minute)
  )

  if (any(lengths != n)) {
    msg <- paste("Inconsistent lengths: year = ", lengths[1],
      ", month = ", lengths[2],
      ", day = ", lengths[3],
      ", hour = ", lengths[4],
      ", minute = ", lengths[5],
      ", second = ", n,
      sep = ""
    )
    errors <- c(errors, msg)
  }

  values <- c(object@year, object@month, object@day, object@hour, object@minute)
  values <- values[is.finite(values)]
  diff <- sum(values - trunc(values))
  if (diff != 0) {
    msg <- "periods must have integer values"
    errors <- c(errors, msg)
  }

  if (length(errors) == 0) {
    TRUE
  } else {
    errors
  }
}`

const rtdal003980Source0005 = `setMethod("initialize", "Period", function(.Object, ...) {
  dots <- list(...)
  names(dots)[!nzchar(allNames(dots))] <- ".Data"
  lens <- unlist(lapply(dots, length), F, F)

  ## if any 0-length components, the entire object is 0-length
  if (any(lens == 0)) {
    for (nm in slotNames(.Object)) {
      slot(.Object, nm) <- numeric()
    }
    validObject(.Object)
    return(.Object)
  }

  len <- max(lens)
  nas <- FALSE
  for (nm in slotNames(.Object)) {
    el <-
      if (is.null(obj <- dots[[nm]])) {
        rep.int(0L, len)
      } else {
        if (length(obj) < len) {
          rep_len(obj, len)
        } else {
          obj
        }
      }
    nas <- nas | is.na(el)
    slot(.Object, nm) <- el
  }

  ## If any component has NAs the entire object should have those NAs
  if (any(nas)) {
    for (nm in slotNames(.Object)) {
      slot(.Object, nm)[nas] <- NA_real_
    }
  }

  validObject(.Object)
  .Object
})`

const rtdal003980Source0006 = `setMethod("show", signature(object = "Period"), function(object) {
  if (length(object@.Data) == 0) {
    cat("<Period[0]>\n")
  } else {
    print(format(object))
  }
})`

const rtdal003980Source0007 = `format.Period <- function(x, ...) {
  if (length(x) == 0) {
    return(character())
  }

  show <- paste(
    x@year, "y ", x@month, "m ", x@day, "d ",
    x@hour, "H ", x@minute, "M ", x@.Data, "S",
    sep = ""
  )
  start <- regexpr("[-1-9]|(0\\.)", show)
  show <- ifelse(start > 0, substr(show, start, nchar(show)), "0S")

  show[is.na(x)] <- NA
  show
}`

const rtdal003980Source0009 = `c.Period <- function(...) {
  dots <- list(...)
  nempty <- sapply(dots, length) != 0
  elements <- lapply(dots[nempty], as.period)
  seconds <- unlist(lapply(elements, slot, ".Data"))
  # don't keep names for slots
  elements <- unname(elements)
  years <- unlist(lapply(elements, slot, "year"))
  months <- unlist(lapply(elements, slot, "month"))
  days <- unlist(lapply(elements, slot, "day"))
  hours <- unlist(lapply(elements, slot,  "hour"))
  minutes <- unlist(lapply(elements, slot, "minute"))
  new("Period",
    seconds, year = years, month = months,
    day = days, hour = hours, minute = minutes
  )
}`

