const rtdal003980Source0017 = `period <- function(num = NULL, units = "second", ...) {
  if (is.character(num)) {
    parse_period(num)
  } else {
    out1 <- .period_from_num(num, units)
    out2 <- .period_from_units(list(...))
    if (is.null(out1) && is.null(out2)) {
      new("Period", numeric())
    } else if (is.null(out1)) {
      out2
    } else if (is.null(out2)) {
      out1
    } else {
      c(out1, out2)
    }
  }
}`

const rtdal003980Source0034 = `seconds_to_period <- function(x) {
  span <- as.double(x)
  remainder <- abs(span)
  newper <- period(second = rep(0, length(x)))

  slot(newper, "day") <- remainder %/% (3600 * 24)
  remainder <- remainder %% (3600 * 24)

  slot(newper, "hour") <- remainder %/% (3600)
  remainder <- remainder %% (3600)

  slot(newper, "minute") <- remainder %/% (60)

  slot(newper, ".Data") <- remainder %% (60)

  newper * sign(span)
}`

const rtdal003980Source0035 = "summary.Period <- function(object, ...) {\n  nas <- is.na(object)\n  object <- object[!nas]\n  persecs <- period_to_seconds(object)\n  qq <- stats::quantile(persecs)\n  qq <- c(qq[1L:3L], mean(persecs), qq[4L:5L])\n  qq <- seconds_to_period(qq)\n  qq <- as.character(qq)\n  names(qq) <- c(\n    \"Min.\", \"1st Qu.\", \"Median\", \"Mean\", \"3rd Qu.\",\n    \"Max.\"\n  )\n  if (any(nas)) {\n    c(qq, `NA's` = sum(nas))\n  } else {\n    qq\n  }\n}"

