const rtdal003988Source0001 = `update.POSIXt <- function(object, ...,
                          roll_dst = c("NA", "post"),
                          week_start = getOption("lubridate.week.start", 7),
                          roll = NULL, simple = NULL) {
  if (!is.null(simple)) roll <- simple
  do.call(update_datetime, c(
    list(object, week_start = week_start, roll_dst = roll_dst, roll = roll),
    list(...)
  ))
}`

const rtdal003988Source0002 = "update_datetime <- function(object, years = NULL, months = NULL,\n                            days = NULL, mdays = NULL, ydays = NULL, wdays = NULL,\n                            hours = NULL, minutes = NULL, seconds = NULL, tzs = NULL,\n                            roll_month = \"full\",\n                            roll_dst = c(\"NA\", \"post\"),\n                            roll = NULL,\n                            week_start = 7,\n                            exact = FALSE) {\n  roll_dst <- normalize_roll_dst(roll_dst, roll, 1)\n  week_start <- as_week_start(week_start)\n\n  if (!is.null(days)) {\n    if (!is.null(mdays)) {\n      stop(\"Only one of `days` and `mdays` must be supplied\")\n    }\n    mdays <- days\n  }\n\n  updates <- list(\n    year = years, month = months,\n    mday = mdays, wday = wdays, yday = ydays,\n    hour = hours, minute = minutes, second = seconds\n  )\n  timechange::time_update(\n    object, updates = normalize_units_length(updates), tz = tzs,\n    roll_dst = roll_dst, roll_month = roll_month,\n    week_start = as_week_start(week_start),\n    exact = exact\n  )\n}"

const rtdal003988Source0004 = "as_week_start <- function(x) {\n  if (is.numeric(x)) {\n    if (x > 7 || x < 1) {\n      stop(\"Invalid 'week_start' argument; must be between 1 and 7\")\n    }\n    return(x)\n  }\n\n  if (length(x) != 1L)\n    stop(\"Invalid `week_start` argument; must be of length 1\")\n\n  if (!is.character(x))\n    stop(\"Invalid `week_start` argument; must be a number in 1-7 (Monday based) or string day of the week\", call. = FALSE)\n\n  # Use pmatch to also capture abbreviations.\n  english_idx <- pmatch(x, c(\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\", \"Saturday\", \"Sunday\"))\n  if (!is.na(english_idx)) {\n    return(english_idx)\n  }\n\n  # Other locales might use abbreviations that are not so pmatch-friendly; try full first, then partial.\n  native_full_idx <- match(x, .get_locale_regs()$wday_names$full)\n  if (!is.na(native_full_idx)) {\n    return(native_full_idx)\n  }\n\n  native_abbr_idx <- match(x, .get_locale_regs()$wday_names$abr)\n  if (!is.na(native_abbr_idx)) {\n    return(native_abbr_idx)\n  }\n}"

const rtdal003988Source0005 = `update_posixt_old <- function(object, ..., simple = FALSE) {
  if (!length(object)) {
    return(object)
  }
  date <- as.POSIXlt(object)

  ## adjudicate units input
  units <- list(...)
  names(units) <- standardise_lt_names(names(units))

  if (!is.null(new_tz <- units$tz)) {
    units$tz <- NULL
  }

  day.units <- c("day", "wday", "mday", "yday")
  wunit <- day.units %in% names(units)

  if (n <- sum(wunit)) {
    if (n > 1) stop("conflicting days input")
    uname <- day.units[wunit]
    if (uname != "mday") {
      ## we compute everything with mdays (operating with ydays doesn't work)
      if (uname != "day") {
        if (uname == "yday" & !is.null(units$year)) {
          warning("Updating on both 'year' and 'yday' can lead to wrong results. See bug #319.", call. = F)
        }
        diff <- units[[uname]] - date[[uname]] - 1
        units[[uname]] <- diff + date$mday
      }
      names(units)[names(units) == uname] <- "mday"
    }
  }

  if (!is.null(units$mon)) units$mon <- units$mon - 1
  if (!is.null(units$year)) units$year <- units$year - 1900

  ## make new date-times
  date <- unclass(date)

  date[names(units)] <- units
  date[c("wday", "yday")] <- list(wday = NA, yday = NA)

  ## unbalanced POSIXlt often results in R crashes
  maxlen <- max(unlist(lapply(date, length)))

  if (maxlen > 1) {
    for (nm in names(date)) {
      if (length(date[[nm]]) != maxlen) {
        date[[nm]] <- rep_len(date[[nm]], maxlen)
      }
    }
  }

  class(date) <- c("POSIXlt", "POSIXt")
  if (!is.null(new_tz)) {
    attr(date, "tzone") <- new_tz
  }

  ## fit to timeline
  ## POSIXct format avoids negative and NA elements in POSIXlt format
  fit_to_timeline(date, class(object)[[1]], simple = simple)
}`

const rtdal003988Source0006 = `is_zero_hms <- function(hours = NULL, minutes = NULL, seconds = NULL, tzs = NULL, ...) {
  is.null(tzs) &&
    (is.null(hours) || sum(hours, na.rm = TRUE) == 0) &&
    (is.null(minutes) || sum(minutes, na.rm = TRUE) == 0) &&
    (is.null(seconds) || sum(seconds, na.rm = TRUE) == 0)
}`

const rtdal003988Source0007 = `update.Date <- function(object, ...) {
  out <- update_datetime(object, ...)
  ## lubridate's missing hms component checks for actual zeros. Not a great idea as the
  ## return type is unpredictable but we are stuck with it.
  if (is.POSIXct(out) && is_zero_hms(...))
    as_date(out)
  else
    out
}`

const rtdal003988Source0008 = `fit_to_timeline <- function(lt, class = "POSIXct", simple = FALSE) {
  if (class != "POSIXlt" && class != "POSIXct") {
    stop("class argument must be POSIXlt or POSIXct")
  }

  if (simple) {
    if (class == "POSIXct") {
      as.POSIXct(lt)
    } else {
      as.POSIXlt(as.POSIXct(lt))
    }
  } else {

    ## fall break - DST only changes if it has to
    ct <- as.POSIXct(lt)
    lt2 <- as.POSIXlt(ct)

    dstdiff <- !is.na(ct) & (lt$isdst != lt2$isdst)
    if (any(dstdiff)) {
      dlt <- lt[dstdiff]
      dlt2 <- lt2[dstdiff]
      dlt$isdst <- dlt2$isdst
      dlt$zone <- dlt2$zone
      dlt$gmtoff <- dlt2$gmtoff
      dct <- as.POSIXct(dlt) # should directly match if not in gap

      if (class == "POSIXct") {
        ct[dstdiff] <- dct
      } else {
        lt2[dstdiff] <- dlt
      }

      chours <- format.POSIXlt(as.POSIXlt(dct), "%H", usetz = FALSE)
      lhours <- format.POSIXlt(dlt, "%H", usetz = FALSE)

      any <- any(hdiff <- chours != lhours)
      if (!is.na(any) && any) {
        if (class == "POSIXct") {
          ct[dstdiff][hdiff] <- NA
        } else {
          lt2[dstdiff][hdiff] <- NA
        }
      }
    }
    if (class == "POSIXct") ct else lt2
  }
}`

