const rtdal003990Source0016 = "vec_proxy.Interval <- function(x, ...) {\n  # Ordered in such a way that the start date controls interval ordering.\n  # Ties in the start date are resolved by placing shorter intervals first.\n  out <- list(\n    start = x@start,\n    span = x@.Data\n  )\n\n  # Push names onto the `span` column (i.e. `.Data`) so they get sliced and restored\n  names <- names(x)\n  if (!is.null(names)) {\n    names(out$span) <- names\n  }\n\n  n <- length(out$start)\n\n  vctrs::new_data_frame(out, n = n)\n}"

const rtdal003990Source0017 = `vec_restore.Interval <- function(x, to, ...) {
  out <- new(
    "Interval",
    x$span,
    start = x$start,
    tzone = tz(x$start)
  )

  names <- names(x$span)
  if (!is.null(names)) {
    names(out) <- names
  }

  out
}`

const rtdal003990Source0018 = `vec_ptype2.Interval.Interval <- function(x, y, ...) {
  new_empty_interval(tzone = tz_union(x, y))
}`

const rtdal003990Source0019 = `vec_cast.Interval.Interval <- function(x, to, ...) {
  x_tzone <- x@tzone
  to_tzone <- to@tzone

  if (identical(x_tzone, to_tzone)) {
    return(x)
  }

  x_span <- x@.Data
  x_start <- x@start

  start <- with_tz(x_start, to_tzone)

  new("Interval", x_span, start = start, tzone = to_tzone)
}`

const rtdal003990Source0021 = `tz_union <- function(x, y) {
  x_tzone <- x@tzone
  y_tzone <- y@tzone

  if (tz_is_local(x_tzone)) {
    y_tzone
  } else {
    x_tzone
  }
}`

