const rtdal004004Source0001 = `test_that(".get_train_set can find non NA dates", {
  x <- suppressWarnings(suppressMessages(ymd(c(rep(NA, 199), 20130213))))
  expect_equal(x, as.Date(as.POSIXct(c(rep(NA, 199), "2013-02-13"), tz = "UTC")))
})`

const rtdal004004Source0002 = `test_that("guess_format works with missing entries", {
  expect_equal(
    guess_formats("01-01-10", "mdy"),
    guess_formats(c("01-01-10", NA), "mdy")
  )
  expect_null(guess_formats(NA, "mdy"))
})`

const rtdal004004Source0003 = `test_that("guess_format consistently adds 0b for B and b", {
  # Abbreviated month names:
  expect_true("Obdy" %in% names(guess_formats("jan 3 2010", "bdy")))
  expect_true("Obdy" %in% names(guess_formats("jan 3 2010", "Bdy")))
  # Full month names:
  expect_true("Obdy" %in% names(guess_formats("January 5 1999", "Bdy")))
  expect_true("Obdy" %in% names(guess_formats("January 5 1999", "Bdy")))
})`

const rtdal004004Source0004 = `test_that("b/B give complete and equivalent results for trained parsing", {
  full <- c("february  14, 2004", "January 5 1999")
  mixed <- c("jan 3 2010", "January 5 1999")
  short <- c("jan 3 2010", "Jan 1, 1999")
  expect_equal(
    parse_date_time(full, "bdy"),
    parse_date_time(full, "Bdy")
  )
  expect_equal(
    parse_date_time(mixed, "bdy"),
    parse_date_time(mixed, "Bdy")
  )
  expect_equal(
    parse_date_time(short, "bdy"),
    parse_date_time(short, "Bdy")
  )

  expect_false(anyNA(parse_date_time(full, "bdy")))
  expect_false(anyNA(parse_date_time(mixed, "bdy")))
  expect_false(anyNA(parse_date_time(short, "bdy")))
})`

