const rtdal004015Source0024 = `test_that("parse_date_time handles multiple month formats correctly", {
  dates <- c("09-01-17", "02-Sep-17")
  expect_equal(
    parse_date_time(dates, orders = c("dmy"), locale = "C"),
    ymd(c("2017-01-09", "2017-09-02"), tz = "UTC")
  )
  expect_equal(
    parse_date_time(dates, orders = c("dby"), locale = "C", quiet = T),
    ymd(c(NA, "2017-09-02"), tz = "UTC")
  )

  ## mdy & dby
  expect_equal(
    parse_date_time(dates, orders = c("mdy", "dby")),
    ymd(c("2017-09-01", "2017-09-02"), tz = "UTC")
  )

  ## mdY & dby/Y
  expect_equal(
    parse_date_time(c("09-01-2017", "02-Sep-17"), orders = c("mdY", "dby")),
    ymd(c("2017-09-01", "2017-09-02"), tz = "UTC")
  )

  expect_equal(
    parse_date_time(c("09-01-2017", "02-Sep-2017"), orders = c("mdY", "dbY")),
    ymd(c("2017-09-01", "2017-09-02"), tz = "UTC")
  )

  ## mdy/Y & dby/Y, with no mdy/Y in x
  expect_equal(
    parse_date_time("09-01-17", orders = c("mdy", "dby", "dbY")),
    ymd(c("2017-09-01"), tz = "UTC")
  )
})`

