const rtdal004015Source0037 = `test_that("AM/PM indicators are parsed correctly", {
  expect_equal(
    parse_date_time2("12/17/1996 04:00:00  PM", "mdYHMSp"),
    ymd_hms("1996-12-17 16:00:00")
  )
  expect_equal(
    parse_date_time2("12/17/1996 04:00:00  PM", "mdYHMSOp"),
    ymd_hms("1996-12-17 16:00:00")
  )
  expect_equal(
    parse_date_time2("12/17/1996 04:00:00  AM", "mdYHMSp"),
    ymd_hms("1996-12-17 04:00:00")
  )
  expect_equal(
    parse_date_time2("12/17/1996 04:00:00  PM", "mdYHMSp", tz = "Europe/Berlin"),
    ymd_hms("1996-12-17 16:00:00", tz = "Europe/Berlin")
  )
  expect_equal(
    parse_date_time2("12/17/1996 04:00:00  TM", "mdYHMSp"),
    make_datetime(NA)
  )
  expect_equal(
    as.POSIXct(fast_strptime("1996-05-17 04:00:00 PM", "%Y-%m-%d %H:%M:%S %Op")),
    ymd_hms("1996-05-17 16:00:00")
  )
  expect_equal(ymd_hms("1996-05-17 04:00:00 PM"), ymd_hms("1996-05-17 16:00:00"))
  expect_equal(ydm_hms("1996-17-05 04:00:00 PM"), ydm_hms("1996-17-05 16:00:00"))
  expect_equal(dmy_hms("17-05-1996 04:00:00 PM"), dmy_hms("17-05-1996 16:00:00"))
  expect_equal(
    parse_date_time("2010-Dec-02 03:59:59 PM", "YmdT"),
    parse_date_time2("2010-12-02 15:59:59", "YmdHMS")
  )
  expect_equal(
    parse_date_time("2010-Dec-02 03:59:59 PM", "YmdT"),
    parse_date_time2("2010-12-02 15:59:59", "YmdHMS")
  )
  expect_equal(
    parse_date_time("2010-Dec-02 03:59 PM", "YmdR"),
    parse_date_time2("2010-12-02 15:59:00", "YmdHMS")
  )
  expect_equal(
    parse_date_time("2010-Dec-02 03 PM", "Ymdr"),
    parse_date_time2("2010-12-02 15:00:00", "YmdHMS")
  )
})`

