const rtdal004050Source0001 = "luz_save <- function(obj, path, ...) {\n  rlang::check_dots_empty()\n  # dangling environments might be in the `obj` search path causing problems\n  # during saving. `gc()` is a good practice to make sure they are cleaned up\n  # before saving.\n  gc()\n\n  if (!inherits(obj, \"luz_module_fitted\"))\n    rlang::abort(\"luz_save only works with 'luz_module_fitted_objects' and got {class(obj)[1]}\")\n\n  # avoid warning because luz will always be available when reloading\n  # because we reload with `luz_load()`.\n  suppressWarnings({\n    serialized_model <- model_to_raw(obj$model)\n    obj$ctx$.serialized_model <- serialized_model\n    obj$ctx$.serialization_version <- 2L\n    o <- saveRDS(obj, path)\n  })\n\n  invisible(o)\n}"

const rtdal004050Source0002 = `luz_load <- function(path) {
  obj <- readRDS(file = path)

  if (is.null(obj$ctx$.serialization_version))
    return(legacy_luz_load(path))

  model <- model_from_raw(obj$ctx$.serialized_model)

  obj$model <- model
  obj$ctx$.serialized_model <- NULL
  obj$ctx$.serialization_version <- NULL

  obj
}`

const rtdal004050Source0003 = `legacy_luz_load <- function(path) {
  obj <- readRDS(file = path)
  model <- model_from_raw(obj$ctx$.serialized_model)
  bind_context(model, obj$ctx)
  obj$model <- model
  obj$ctx$model <- model
  rm(envir = obj$ctx, list = ".serialized_model")
  obj
}`

const rtdal004050Source0004 = `luz_load_model_weights <- function(obj, path, ...) {
  saved_model <- torch::torch_load(path, ...)
  obj$model$load_state_dict(saved_model$state_dict())
  # we return NULL to make sure people don't expect it to return a copy of obj
  invisible(NULL)
}`

const rtdal004050Source0005 = `luz_save_model_weights <- function(obj, path) {
  # 'package:luz' may not be available when loading
  suppressWarnings({
    o <- torch::torch_save(obj$model, path)
  })
  invisible(o)
}`

