const rtdal004053Source0001 = `get_device <- function() {
  if (torch::cuda_is_available())
    "cuda"
  else
    "cpu"
}`

const rtdal004053Source0002 = `get_ds <- torch::dataset(
  initialize = function(len = 100, x_size = 10, y_size = 1, fixed_values = FALSE) {
    self$len <- len
    self$x <- torch::torch_randn(size = c(len, x_size))
    self$y <- torch::torch_randn(size = c(len, y_size))
  },
  .getitem = function(i) {
    list(
      x = self$x[i,..],
      y = self$y[i,..]
    )
  },
  .length = function() {
    self$len
  }
)`

const rtdal004053Source0003 = `get_binary_ds <- torch::dataset(
  inherit = get_ds,
  initialize = function(...) {
    super$initialize(...)
    self$y <- torch::torch_randint(low = 0,high = 2, size = self$y$shape)
  }
)`

const rtdal004053Source0004 = `get_categorical_ds <- torch::dataset(
  inherit = get_ds,
  initialize = function(num_classes = 10,...) {
    super$initialize(...)
    self$y <- torch::torch_randint(low = 1,high = num_classes + 1, size = self$y$shape,
                                   dtype = torch::torch_long()) %>%
      torch::torch_squeeze()

  }
)`

const rtdal004053Source0005 = `get_dl <- function(batch_size = 10, ...) {
  torch::dataloader(get_ds(...), batch_size = batch_size)
}`

const rtdal004053Source0006 = `get_binary_dl <- function(batch_size = 10,...) {
  torch::dataloader(get_binary_ds(...), batch_size = batch_size)
}`

const rtdal004053Source0007 = `get_categorical_dl<- function(batch_size = 10,...) {
  torch::dataloader(get_categorical_ds(...), batch_size = batch_size)
}`

const rtdal004053Source0008 = `get_test_dl <- function(batch_size = 10, ...) {
  torch::dataloader(get_ds(...), batch_size = batch_size, shuffle = FALSE)
}`

const rtdal004053Source0009 = `get_model <- function() {
  torch::nn_module(
    initialize = function(input_size, output_size) {
      self$fc <- torch::nn_linear(prod(input_size), prod(output_size))
      self$output_size <- output_size
    },
    forward = function(x) {
      out <- x %>%
        torch::torch_flatten(start_dim = 2) %>%
        self$fc()
      out$view(c(x$shape[1], self$output_size))
    }
  )
}`

