const rtdal004071Source0001 = `test_that("serialization works as expected", {

  torch::torch_manual_seed(1)
  set.seed(1)

  model <- get_model()
  dl <- get_dl()

  mod <- model %>%
    setup(
      loss = torch::nn_mse_loss(),
      optimizer = torch::optim_adam,
    )

  output <- mod %>%
    set_hparams(input_size = 10, output_size = 1) %>%
    fit(dl, verbose = FALSE, epochs = 1)

  path <- tempfile(pattern="rds")
  luz_save(output, path)

  test <- get_test_dl()

  expected_predictions <- predict(output, test)
  params <- output$model$state_dict()
  rm(output)
  gc()

  output <- luz_load(path)

  params2 <- output$model$state_dict()
  actual_predictions <- predict(output, test)

  expect_equal(
    as.array(actual_predictions$to(device="cpu")),
    as.array(expected_predictions$to(device="cpu"))
  )
})`

const rtdal004071Source0002 = "test_that(\"serialization works when model uses `ctx` in forward\", {\n\n  model <- torch::nn_module(\n    initialize = function() {\n      self$fc <- torch::nn_linear(10, 1, bias = FALSE)\n    },\n    forward = function(x) {\n      if (ctx$training)\n        self$fc(torch::torch_ones_like(x))\n      else\n        self$fc(torch::torch_zeros_like(x))\n    }\n  )\n\n  dl <- get_dl()\n\n  mod <- model %>%\n    setup(\n      loss = torch::nn_mse_loss(),\n      optimizer = torch::optim_adam,\n    )\n\n  output <- mod %>%\n    set_hparams() %>%\n    fit(dl, verbose = FALSE, epochs = 1)\n\n\n  pred <- predict(output, dl)\n  expect_equal(as.array(pred$cpu()), as.array(torch::torch_zeros(100,1)))\n\n  output$ctx$training <- TRUE\n\n  path <- tempfile(pattern=\"rds\")\n  luz_save(output, path)\n\n  rm(output)\n  gc()\n\n  output <- luz_load(path)\n  pred <- predict(output, dl)\n  expect_equal(\n    as.array(pred$to(device=\"cpu\")),\n    as.array(torch::torch_zeros(100,1))\n  )\n})"

const rtdal004071Source0003 = `test_that("save and load model weights", {

  model <- get_model()
  dl <- get_dl()

  mod <- model %>%
    setup(
      loss = torch::nn_mse_loss(),
      optimizer = torch::optim_adam,
    )

  output <- mod %>%
    set_hparams(input_size = 10, output_size = 1) %>%
    fit(dl, verbose = FALSE, epochs = 1)

  pars <- lapply(output$model$parameters, function(x) x$clone())

  tmp <- tempfile(fileext = "rds")
  luz_save_model_weights(output, tmp)

  # modify parameters
  torch::with_no_grad({
    output$model$fc$weight$add_(5)
  })

  expect_not_equal_to_tensor(output$model$parameters$fc.weight, pars$fc.weight)

  #restore parameters
  luz_load_model_weights(output, tmp)

  pars2 <- output$model$parameters

  expect_equal_to_tensor(pars2$fc.weight, pars$fc.weight)
  expect_equal_to_tensor(pars2$fc.bias, pars$fc.bias)
})`

